-- Require independent report-view permission for the advanced financial report RPC.
CREATE OR REPLACE FUNCTION public.get_advanced_finance_report(p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_consultant_id uuid DEFAULT NULL::uuid, p_service_id uuid DEFAULT NULL::uuid, p_gateway text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_from timestamptz:=coalesce(p_from,date_trunc('month',now())); v_to timestamptz:=coalesce(p_to,now()); v_ledger jsonb; v_income numeric:=0; v_expenses numeric:=0; v_net numeric:=0; v_tx_count int:=0; v_appointments int:=0; v_paid_appointments int:=0; v_cancelled int:=0; v_receipts numeric:=0; v_unlinked numeric:=0; v_mismatch numeric:=0; v_result jsonb;
begin
 if not coalesce(public.has_admin_permission('finance.reports.view'),false) then raise exception 'permission denied'; end if;
 v_ledger:=public.get_finance_ledger(v_from,v_to,p_consultant_id,p_service_id,p_gateway);
 v_income:=coalesce((v_ledger->>'income')::numeric,0); v_expenses:=coalesce((v_ledger->>'expenses')::numeric,0); v_net:=coalesce((v_ledger->>'net_profit')::numeric,0); v_tx_count:=coalesce((v_ledger->>'transaction_count')::int,0);
 select count(*)::int,count(*) filter(where a.payment_status in('paid','completed'))::int,count(*) filter(where a.status='cancelled')::int into v_appointments,v_paid_appointments,v_cancelled from appointments a where a.scheduled_at>=v_from and a.scheduled_at<v_to and(p_consultant_id is null or a.consultant_id=p_consultant_id)and(p_service_id is null or a.service_id=p_service_id);
 select coalesce(sum(pr.amount),0) into v_receipts from payment_receipts pr left join appointments a on a.id=pr.appointment_id where pr.status='approved' and pr.submitted_at>=v_from and pr.submitted_at<v_to and(p_consultant_id is null or a.consultant_id=p_consultant_id)and(p_service_id is null or a.service_id=p_service_id);
 select coalesce(sum(pr.amount),0) into v_unlinked from payment_receipts pr left join appointments a on a.id=pr.appointment_id where pr.status='approved' and pr.finance_transaction_id is null and pr.submitted_at>=v_from and pr.submitted_at<v_to and(p_consultant_id is null or a.consultant_id=p_consultant_id)and(p_service_id is null or a.service_id=p_service_id);
 select coalesce(sum(abs(pr.amount-ft.amount)),0) into v_mismatch from payment_receipts pr join finance_transactions ft on ft.id=pr.finance_transaction_id left join appointments a on a.id=ft.appointment_id where pr.status='approved' and pr.submitted_at>=v_from and pr.submitted_at<v_to and pr.amount<>ft.amount and(p_consultant_id is null or a.consultant_id=p_consultant_id)and(p_service_id is null or a.service_id=p_service_id)and(p_gateway is null or p_gateway='' or coalesce(ft.gateway,a.payment_gateway)=p_gateway);
 v_result=jsonb_build_object('from',v_from,'to',v_to,'income',v_income,'expenses',v_expenses,'consultant_paid',coalesce((select sum(cs.net_amount) from consultant_settlements cs where cs.status='paid' and cs.paid_at>=v_from and cs.paid_at<v_to and(p_consultant_id is null or cs.consultant_id=p_consultant_id)),0),'net_profit',v_net,'margin',case when v_income>0 then round(v_net/v_income*100,2) else 0 end,'transaction_count',v_tx_count,'appointments',v_appointments,'paid_appointments',v_paid_appointments,'cancelled',v_cancelled,'payment_conversion',case when v_appointments>0 then round(v_paid_appointments::numeric/v_appointments*100,2) else 0 end,'reconciliation',jsonb_build_object('approved_receipts',v_receipts,'receipt_without_transaction',v_unlinked,'receipt_transaction_mismatch',v_mismatch,'status',case when v_unlinked=0 and v_mismatch=0 and abs(v_receipts-v_income)<.01 then 'balanced' else 'warning' end));
 v_result:=v_result||jsonb_build_object('transactions',coalesce((select jsonb_agg(to_jsonb(x)) from(select ft.occurred_at,ft.amount,ft.gateway,ft.payment_method,ft.status,ft.tracking_code,ft.reference_id,ft.description,c.name consultant_name,s.name service_name from finance_transactions ft left join appointments a on a.id=ft.appointment_id left join consultants c on c.id=a.consultant_id left join services s on s.id=a.service_id where ft.transaction_type='income' and ft.status in('paid','approved','success','completed') and ft.occurred_at>=v_from and ft.occurred_at<v_to and(p_consultant_id is null or a.consultant_id=p_consultant_id)and(p_service_id is null or a.service_id=p_service_id)and(p_gateway is null or p_gateway='' or coalesce(ft.gateway,a.payment_gateway)=p_gateway) order by ft.occurred_at desc)x),'[]'::jsonb),'expenses_detail',coalesce((select jsonb_agg(to_jsonb(x)) from(select e.expense_date,e.amount,e.payment_method,e.reference_number,e.reference_id,e.description,ec.name category_name from expenses e left join expense_categories ec on ec.id=e.category_id where e.expense_date>=v_from::date and e.expense_date<=v_to::date and p_consultant_id is null and p_service_id is null and(p_gateway is null or p_gateway='') order by e.expense_date desc)x),'[]'::jsonb));
 return v_result;
end;$function$;
